/* @author MILO-GAO(高振銘)@2020 */ package page2020.data;import java.util.ArrayList;import java.util.List;import page2020.core.Name;public class TableData extends Name<TableData> {	private Integer length;	private List<String> keys;	private List<List<Object>> data;	private String username;	private String appName;	private boolean serial;	public TableData() {		this.length = 0;		this.keys = new ArrayList<String>();		this.data = new ArrayList<List<Object>>();	}	public TableData(List<String> keys, List<List<Object>> data) {		this.length = keys.size();		this.keys = keys;		this.data = data;	}	public TableData copy(int begin, int length) {		TableData copy = new TableData();		List<String> copyKeys = copy.getKeys();		List<List<Object>> copyData = copy.getData();		int index = begin;		if (index < this.length) {			for (int i=0; i < length; i++) {							copyKeys.add(this.keys.get(index));				copyData.add(this.data.get(index));				index += 1;				if (index == this.length) {					break;				}			}		}		copy.setLength(copyKeys.size());		return copy;	}	public TableData document(String username, String appName, boolean serial) {		this.username = username;		this.appName = appName;		this.serial = serial;		return this;	}	public Integer getLength() {		return length;	}	public void setLength(Integer length) {		this.length = length;	}	public List<String> getKeys() {		return keys;	}	public void setKeys(List<String> keys) {		this.keys = keys;	}	public List<List<Object>> getData() {		return data;	}	public void setData(List<List<Object>> data) {		this.data = data;	}	public String getUsername() {		return username;	}	public void setUsername(String username) {		this.username = username;	}	public String getAppName() {		return appName;	}	public void setAppName(String appName) {		this.appName = appName;	}	public boolean isSerial() {		return serial;	}	public void setSerial(boolean serial) {		this.serial = serial;	}}